early:
recursive fn make()->i64[2]{return[7,8];}
recursive fn run(early:bool)->bool{return make()==({if early{return true;}[7,8]});}
fn main(){assert(run(true));assert(run(false));print("early");}

projected:
struct H{items:i64[2]}
recursive fn make()->H{return H{items:[7,8]};}
fn main(){var a:i64[2]=[7,8];assert(make().items==a);assert(a==make().items);print("projected");}

mutation_ref:
var a:i64[2]=[7,8];
recursive fn change()->i64[2]&{a[0]=9;return a;}
fn main(){assert(!(a==change()));assert(a[0]==9);print("mutation_ref");}
